files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --accent: #7c6ff0;
  --accent-hover: #9a8ff5;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --border: #3e3e5a;
  --danger: #f06f6f;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
  line-height: 1.5;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 28px 24px;
  width: 100%;
  max-width: 560px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--text);
}

.subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 24px;
}

.course-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 24px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
}

input, select {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.15s, box-shadow 0.15s;
  width: 100%;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(124, 111, 240, 0.3);
}

input::placeholder {
  color: var(--text-muted);
  opacity: 0.7;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  min-height: 44px;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.btn.primary:active {
  transform: scale(0.98);
}

.btn.primary:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.btn.remove {
  background: transparent;
  color: var(--danger);
  font-size: 1.2rem;
  padding: 4px 10px;
  min-height: 36px;
  border-radius: 6px;
  line-height: 1;
}

.btn.remove:hover {
  background: rgba(240, 111, 111, 0.15);
}

.btn.remove:active {
  transform: scale(0.92);
}

.btn.remove:focus-visible {
  outline: 3px solid var(--danger);
  outline-offset: 2px;
}

.gpa-display {
  background: var(--bg);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.gpa-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.gpa-value {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--accent);
  line-height: 1.2;
}

.gpa-detail {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.course-list-section h2 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.course-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.course-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--bg);
  border-radius: 8px;
  padding: 12px 14px;
  border-left: 4px solid var(--accent);
}

.course-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.course-name {
  font-weight: 600;
  font-size: 1rem;
  overflow-wrap: break-word;
  word-break: break-word;
}

.course-meta {
  font-size: 0.85rem;
  color: var(--text-muted);
}

.course-grade {
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--accent);
  flex-shrink: 0;
}

.empty-message {
  color: var(--text-muted);
  font-size: 0.95rem;
  text-align: center;
  padding: 16px 0;
  font-style: italic;
}

.empty-message.hidden {
  display: none;
}

@media (min-width: 480px) {
  .course-form {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-end;
  }
  .form-group {
    flex: 1 1 120px;
  }
  .form-group:first-child {
    flex: 2 1 160px;
  }
  .btn.primary {
    flex: 0 0 auto;
  }
}

@media (max-width: 400px) {
  .card {
    padding: 20px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .gpa-value {
    font-size: 2rem;
  }
  .course-item {
    flex-wrap: wrap;
  }
}

(function () {
  'use strict';

  var GRADE_POINTS = { A: 4.0, B: 3.0, C: 2.0, D: 1.0, F: 0.0 };

  var courses = [];

  var form = document.getElementById('course-form');
  var nameInput = document.getElementById('course-name');
  var creditInput = document.getElementById('credit-hours');
  var gradeSelect = document.getElementById('letter-grade');
  var listEl = document.getElementById('course-list');
  var gpaValueEl = document.getElementById('gpa-value');
  var gpaDetailEl = document.getElementById('gpa-detail');
  var emptyMsg = document.getElementById('empty-message');

  function calculateGPA() {
    var totalCredits = 0;
    var totalPoints = 0;
    for (var i = 0; i < courses.length; i++) {
      var c = courses[i];
      totalCredits += c.credits;
      totalPoints += c.credits * GRADE_POINTS[c.grade];
    }
    if (totalCredits === 0) {
      return { gpa: null, totalCredits: 0 };
    }
    return { gpa: totalPoints / totalCredits, totalCredits: totalCredits };
  }

  function render() {
    listEl.innerHTML = '';
    if (courses.length === 0) {
      emptyMsg.classList.remove('hidden');
    } else {
      emptyMsg.classList.add('hidden');
    }

    for (var i = 0; i < courses.length; i++) {
      (function (index) {
        var c = courses[index];
        var li = document.createElement('li');
        li.className = 'course-item';

        var info = document.createElement('div');
        info.className = 'course-info';

        var nameSpan = document.createElement('span');
        nameSpan.className = 'course-name';
        nameSpan.textContent = c.name;

        var metaSpan = document.createElement('span');
        metaSpan.className = 'course-meta';
        metaSpan.textContent = c.credits + ' credit' + (c.credits !== 1 ? 's' : '');

        info.appendChild(nameSpan);
        info.appendChild(metaSpan);

        var gradeSpan = document.createElement('span');
        gradeSpan.className = 'course-grade';
        gradeSpan.textContent = c.grade;

        var removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'btn remove';
        removeBtn.textContent = '\u00d7';
        removeBtn.setAttribute('aria-label', 'Remove ' + c.name);
        removeBtn.addEventListener('click', function () {
          courses.splice(index, 1);
          render();
        });

        li.appendChild(info);
        li.appendChild(gradeSpan);
        li.appendChild(removeBtn);
        listEl.appendChild(li);
      })(i);
    }

    var result = calculateGPA();
    if (result.gpa === null) {
      gpaValueEl.textContent = '\u2014';
      gpaDetailEl.textContent = '';
    } else {
      gpaValueEl.textContent = result.gpa.toFixed(2);
      gpaDetailEl.textContent = 'Total credits: ' + result.totalCredits;
    }
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    var name = nameInput.value.trim();
    var credits = parseFloat(creditInput.value);
    var grade = gradeSelect.value;

    if (!name) {
      nameInput.focus();
      return;
    }
    if (isNaN(credits) || credits <= 0) {
      creditInput.focus();
      return;
    }

    courses.push({ name: name, credits: credits, grade: grade });
    nameInput.value = '';
    creditInput.value = '3';
    gradeSelect.value = 'A';
    nameInput.focus();
    render();
  });

  render();
})();
